import pytest

from renal import OutOfRangeError, creatinine_clearance


class TestHandComputed:
    def test_male_reference_case(self):
        # ((140 - 60) * 72) / (72 * 1.0) = 5760 / 72 = 80.0 exactly
        assert creatinine_clearance(60, 72, 1.0, "male") == pytest.approx(80.0)

    def test_female_factor(self):
        male = creatinine_clearance(60, 72, 1.0, "male")
        female = creatinine_clearance(60, 72, 1.0, "female")
        assert female == pytest.approx(male * 0.85)
        assert female == pytest.approx(68.0)


class TestAgeBoundaries:
    def test_age_min_accepted(self):
        creatinine_clearance(18, 70, 1.0, "male")

    def test_age_max_accepted(self):
        creatinine_clearance(120, 70, 1.0, "male")

    def test_age_below_min_rejected(self):
        with pytest.raises(OutOfRangeError) as ei:
            creatinine_clearance(17, 70, 1.0, "male")
        assert ei.value.field == "age_years"

    def test_age_above_max_rejected(self):
        with pytest.raises(OutOfRangeError) as ei:
            creatinine_clearance(121, 70, 1.0, "male")
        assert ei.value.field == "age_years"


class TestWeightBoundaries:
    def test_weight_min_accepted(self):
        creatinine_clearance(60, 20, 1.0, "male")

    def test_weight_max_accepted(self):
        creatinine_clearance(60, 300, 1.0, "male")

    def test_weight_below_min_rejected(self):
        with pytest.raises(OutOfRangeError) as ei:
            creatinine_clearance(60, 19.9, 1.0, "male")
        assert ei.value.field == "weight_kg"

    def test_weight_above_max_rejected(self):
        with pytest.raises(OutOfRangeError) as ei:
            creatinine_clearance(60, 300.1, 1.0, "male")
        assert ei.value.field == "weight_kg"


class TestCreatinineBoundaries:
    def test_creatinine_min_accepted(self):
        creatinine_clearance(60, 70, 0.1, "male")

    def test_creatinine_max_accepted(self):
        creatinine_clearance(60, 70, 20.0, "male")

    def test_creatinine_below_min_rejected(self):
        with pytest.raises(OutOfRangeError) as ei:
            creatinine_clearance(60, 70, 0.09, "male")
        assert ei.value.field == "serum_creatinine_mg_dl"

    def test_creatinine_above_max_rejected(self):
        with pytest.raises(OutOfRangeError) as ei:
            creatinine_clearance(60, 70, 20.1, "male")
        assert ei.value.field == "serum_creatinine_mg_dl"


class TestZeroCreatinine:
    def test_zero_creatinine_raises_out_of_range_before_division(self):
        # Must surface as OutOfRangeError naming the field, never
        # ZeroDivisionError.
        with pytest.raises(OutOfRangeError) as ei:
            creatinine_clearance(60, 70, 0, "male")
        assert ei.value.field == "serum_creatinine_mg_dl"
        assert ei.value.value == 0


class TestErrorType:
    def test_is_value_error(self):
        # OutOfRangeError should be catchable as ValueError too.
        with pytest.raises(ValueError):
            creatinine_clearance(10, 70, 1.0, "male")

    def test_message_contains_field_and_bounds(self):
        with pytest.raises(OutOfRangeError) as ei:
            creatinine_clearance(150, 70, 1.0, "male")
        msg = str(ei.value)
        assert "age_years" in msg and "120" in msg

